window.ORAKEL_DATEN={"quelle": {"werk": "I Ging – Das Buch der Wandlungen, übersetzt von Richard Wilhelm (Erstausgabe Jena: Diederichs 1924)", "url": "https://projekt-gutenberg.org/authors/richard-wilhelm/books/i-ging/", "lizenz": "Richard Wilhelm starb 1930; der Übersetzungstext ist seit 2001 in Deutschland gemeinfrei (70 Jahre p. m. a.). Entnommen aus der Online-Ausgabe von Projekt Gutenberg-DE; nur Urteil und Bild, ohne Kommentare.", "abgerufen": "2026-10-25"}, "hexagramme": {"1": {"king_wen": 1, "name": "Das Schöpferische", "titel_quelle": "1. KIEN / DAS SCHÖPFERISCHE", "zeichen": "☰☰", "binaer_oben_nach_unten": "111111", "oben": "Himmel", "unten": "Himmel", "bild_trigramme": "Himmel über Himmel", "urteil": "Das Schöpferische wirkt erhabenes Gelingen,\nfördernd durch Beharrlichkeit", "bild": "Des Himmels Bewegung ist kraftvoll.\nSo macht der Edle sich stark und unermüdlich", "quelle": {"url": "https://projekt-gutenberg.org/authors/richard-wilhelm/books/i-ging/chapter/3/", "text": "Richard Wilhelm, I Ging (1924), Projekt Gutenberg-DE"}, "karaoke": {"satz": "Finale · Vollendung", "datei": "lang-f-vollendung", "strophe": "F0", "zeile": "Am-An-fang-war-das-Wort, das-Licht", "start": 0, "gesamt_start": 1638, "stimme": "beide", "melodie": "M", "nr": 55, "pflanze": "Berg-/Kalk-Aster (Aster amellus)", "sektor": 1}}, "2": {"king_wen": 2, "name": "Das Empfangende", "titel_quelle": "2. KUN / DAS EMPFANGENDE", "zeichen": "☷☷", "binaer_oben_nach_unten": "000000", "oben": "Erde", "unten": "Erde", "bild_trigramme": "Erde über Erde", "urteil": "Das Empfangende wirkt erhabenes Gelingen,\nfördernd durch die Beharrlichkeit einer Stute.\nHat der Edle etwas zu unternehmen und will voraus,\nso geht er irre; doch folgt er nach, so findet er Leitung.\nFördernd ist es, im Westen und Süden Freunde zu finden,\nim Osten und Norden der Freunde zu entraten.\nRuhige Beharrlichkeit bringt Heil.", "bild": "Der Zustand der Erde ist die empfangende Hingebung.\nSo trägt der Edle weiträumigen Wesens die Außenwelt.", "quelle": {"url": "https://projekt-gutenberg.org/authors/richard-wilhelm/books/i-ging/chapter/12/", "text": "Richard Wilhelm, I Ging (1924), Projekt Gutenberg-DE", "bild_url": "https://schuledesrades.org/public/iging/buch/sdr-q-5-1-2-2", "hinweis": "Bild fehlt in der Gutenberg-Kapitelseite; Wilhelm-Text aus schuledesrades.org übernommen"}, "karaoke": {"satz": "C · I Ging", "datei": "lang-c-i-ging", "strophe": "C2", "zeile": "die-Er-de-birgt-das-stil-le-Bild", "start": 248, "gesamt_start": 1134, "stimme": "Frau", "melodie": "F", "nr": 34, "pflanze": "Haselwurz (Asarum europaeum)", "sektor": 33}}, "3": {"king_wen": 3, "name": "Die Anfangsschwierigkeit", "titel_quelle": "3. DSCHUN / DIE ANFANGSSCHWIERIGKEIT", "zeichen": "☵☳", "binaer_oben_nach_unten": "010001", "oben": "Wasser", "unten": "Donner", "bild_trigramme": "Wasser über Donner", "urteil": "Die Anfangsschwierigkeit wirkt erhabenes Gelingen.\nFördernd durch Beharrlichkeit.\nMan soll nichts unternehmen.\nFördernd ist es, Gehilfen einzusetzen.", "bild": "Wolken und Donner: das Bild der Anfangsschwierigkeit.\nSo wirkt der Edle entwirrend und ordnend.", "quelle": {"url": "https://projekt-gutenberg.org/authors/richard-wilhelm/books/i-ging/chapter/22/", "text": "Richard Wilhelm, I Ging (1924), Projekt Gutenberg-DE"}, "karaoke": {"satz": "Finale · Vollendung", "datei": "lang-f-vollendung", "strophe": "F0", "zeile": "und-lass-uns-dei-ne-Hüt-te-sein", "start": 24, "gesamt_start": 1662, "stimme": "beide", "melodie": "F", "nr": 58, "pflanze": "Küchenschelle (Pulsatilla vulgaris)", "sektor": 30}}, "4": {"king_wen": 4, "name": "Die Jugendtorheit", "titel_quelle": "4. MONG / DIE JUGENDTORHEIT", "zeichen": "☶☵", "binaer_oben_nach_unten": "100010", "oben": "Berg", "unten": "Wasser", "bild_trigramme": "Berg über Wasser", "urteil": "Jugendtorheit hat Gelingen.\nNicht ich suche den jungen Toren,\nder junge Tor sucht mich.\nBeim ersten Orakel gebe ich Auskunft.\nFragt er zwei-, dreimal, so ist das Belästigung.\nWenn er belästigt, so gebe ich keine Auskunft.\nFördernd ist Beharrlichkeit", "bild": "Unten am Berg kommt ein Quell hervor:\ndas Bild der Jugend.\nSo nährt der Edle durch gründliches Handeln seinen Charakter", "quelle": {"url": "https://projekt-gutenberg.org/authors/richard-wilhelm/books/i-ging/chapter/31/", "text": "Richard Wilhelm, I Ging (1924), Projekt Gutenberg-DE"}, "karaoke": {"satz": "A · Tanz der freundlichen Geister", "datei": "lang-a-tanz-der-freundlichen-geister", "strophe": "A", "zeile": "Der-Him-mel-ruht-im-Was-ser-grund", "start": 80, "gesamt_start": 222, "stimme": "Bariton", "melodie": "M", "nr": 5, "pflanze": "Dach-Hauswurz (Sempervivum tectorum)", "sektor": 50}}, "5": {"king_wen": 5, "name": "Das Warten", "titel_quelle": "5. SÜ / DAS WARTEN (DIE ERNÄHRUNG)", "zeichen": "☵☰", "binaer_oben_nach_unten": "010111", "oben": "Wasser", "unten": "Himmel", "bild_trigramme": "Wasser über Himmel", "urteil": "Das Warten.\nWenn du wahrhaftig bist, so hast du Licht und Gelingen.\nBeharrlichkeit bringt Heil.\nFördernd ist es, das große Wasser zu durchqueren.", "bild": "Wolken steigen am Himmel auf: das Bild des Wartens.\nSo ißt und trinkt der Edle und ist heiter und guter Dinge.", "quelle": {"url": "https://projekt-gutenberg.org/authors/richard-wilhelm/books/i-ging/chapter/6/", "text": "Richard Wilhelm, I Ging (1924), Projekt Gutenberg-DE"}, "karaoke": {"satz": "B · Spiral Roll-out", "datei": "lang-b-spiral-roll-out", "strophe": "B2", "zeile": "Bum, bum, die-Trom-mel-schlägt-im-Takt", "start": 192, "gesamt_start": 706, "stimme": "Bariton", "melodie": "M", "nr": 21, "pflanze": "Weicher Frauenmantel (Alchemilla mollis)", "sektor": 6}}, "6": {"king_wen": 6, "name": "Der Streit", "titel_quelle": "6. SUNG / DER STREIT", "zeichen": "☰☵", "binaer_oben_nach_unten": "111010", "oben": "Himmel", "unten": "Wasser", "bild_trigramme": "Himmel über Wasser", "urteil": "Der Streit: Du bist wahrhaftig und wirst gehemmt.\nSorgliches Innehalten auf halbem Weg bringt Heil.\nZu Ende führen bringt Unheil.\nFördernd ist es, den großen Mann zu sehen.\nNicht fördernd ist es, das große Wasser zu durchqueren.", "bild": "Himmel und Wasser gehen einander entgegengesetzt: das Bild des Streites.\nSo überlegt der Edle bei allen Geschäften, die er tut, den Anfang.", "quelle": {"url": "https://projekt-gutenberg.org/authors/richard-wilhelm/books/i-ging/chapter/27/", "text": "Richard Wilhelm, I Ging (1924), Projekt Gutenberg-DE"}, "karaoke": {"satz": "A · Tanz der freundlichen Geister", "datei": "lang-a-tanz-der-freundlichen-geister", "strophe": "A", "zeile": "Christ-geht-mit-uns-durch-Tau-und-Zeit", "start": 96, "gesamt_start": 238, "stimme": "Bariton", "melodie": "M", "nr": 7, "pflanze": "Berg-/Kalk-Aster (Aster amellus)", "sektor": 56}}, "7": {"king_wen": 7, "name": "Das Heer", "titel_quelle": "7. SCHI / DAS HEER", "zeichen": "☷☵", "binaer_oben_nach_unten": "000010", "oben": "Erde", "unten": "Wasser", "bild_trigramme": "Erde über Wasser", "urteil": "D as Heer braucht Beharrlichkeit\nund einen starken Mann.\nHeil ohne Makel.", "bild": "Inmitten der Erde ist Wasser, das Bild des Heeres.\nSo mehrt der Edle durch Weitherzigkeit gegen das Volk seine Massen.", "quelle": {"url": "https://projekt-gutenberg.org/authors/richard-wilhelm/books/i-ging/chapter/28/", "text": "Richard Wilhelm, I Ging (1924), Projekt Gutenberg-DE"}, "karaoke": {"satz": "D · Begegnung", "datei": "lang-d-begegnung", "strophe": "D0", "zeile": "drei-Spra-chen, und-doch-al-le-gleich", "start": 56, "gesamt_start": 1320, "stimme": "beide", "melodie": "S", "nr": 40, "pflanze": "Weicher Frauenmantel (Alchemilla mollis)", "sektor": 49}}, "8": {"king_wen": 8, "name": "Das Zusammenhalten", "titel_quelle": "8. BI / DAS ZUSAMMENHALTEN", "zeichen": "☵☷", "binaer_oben_nach_unten": "010000", "oben": "Wasser", "unten": "Erde", "bild_trigramme": "Wasser über Erde", "urteil": "Das Zusammenhalten bringt Heil.\n Ergründe das Orakel nochmals,\n ob du Erhabenheit, Dauer und Beharrlichkeit hast;\n dann ist kein Makel da.\nDie Unsicheren kommen allmählich herbei.\n Wer zu spät kommt, hat Unheil.", "bild": "Auf der Erde ist Wasser: das Bild des Zusammenhaltens.\n So haben die Könige der Vorzeit die einzelnen Staaten als\n Lehen vergeben und mit den Lehensfürsten\n freundlichen Verkehr gepflegt.", "quelle": {"url": "https://projekt-gutenberg.org/authors/richard-wilhelm/books/i-ging/chapter/14/", "text": "Richard Wilhelm, I Ging (1924), Projekt Gutenberg-DE"}, "karaoke": {"satz": "Finale · Vollendung", "datei": "lang-f-vollendung", "strophe": "F2", "zeile": "in-Gott-kommt-al-les-nun-zur-Ruh", "start": 232, "gesamt_start": 1870, "stimme": "beide", "melodie": "F", "nr": 64, "pflanze": "Haselwurz (Asarum europaeum)", "sektor": 35}}, "9": {"king_wen": 9, "name": "Des Kleinen Zähmungskraft", "titel_quelle": "9. SIAU TSCHU / DES KLEINEN ZÄHMUNGSKRAFT", "zeichen": "☴☰", "binaer_oben_nach_unten": "110111", "oben": "Wind", "unten": "Himmel", "bild_trigramme": "Wind über Himmel", "urteil": "Des Kleinen Zähmungskraft hat Gelingen.\nDichte Wolken, kein Regen von unserm westlichen\nGebiet.", "bild": "Der Wind fährt über den Himmel hin:\ndas Bild der Zähmungskraft des Kleinen.\nSo verfeinert der Edle die äußere Form seines Wesens.", "quelle": {"url": "https://projekt-gutenberg.org/authors/richard-wilhelm/books/i-ging/chapter/8/", "text": "Richard Wilhelm, I Ging (1924), Projekt Gutenberg-DE"}, "karaoke": {"satz": "B · Spiral Roll-out", "datei": "lang-b-spiral-roll-out", "strophe": "B1", "zeile": "wir-tan-zen, Hand-in-Hand, ins-Land", "start": 120, "gesamt_start": 634, "stimme": "Bariton", "melodie": "S", "nr": 20, "pflanze": "Berg-/Kalk-Aster (Aster amellus)", "sektor": 5}}, "10": {"king_wen": 10, "name": "Das Auftreten", "titel_quelle": "10. LÜ / DAS AUFTRETEN", "zeichen": "☰☱", "binaer_oben_nach_unten": "111011", "oben": "Himmel", "unten": "See", "bild_trigramme": "Himmel über See", "urteil": "Auftreten auf des Tigers Schwanz.\nEr beißt den Menschen nicht. Gelingen.", "bild": "Oben der Himmel, unten der See: das Bild des Auftretens.\nSo unterscheidet der Edle hoch und niedrig\nund festigt dadurch den Sinn des Volkes.", "quelle": {"url": "https://projekt-gutenberg.org/authors/richard-wilhelm/books/i-ging/chapter/59/", "text": "Richard Wilhelm, I Ging (1924), Projekt Gutenberg-DE"}, "karaoke": {"satz": "B · Spiral Roll-out", "datei": "lang-b-spiral-roll-out", "strophe": "B1", "zeile": "die-Gug-ge-spielt-am-In-sel-strand", "start": 112, "gesamt_start": 626, "stimme": "Bariton", "melodie": "M", "nr": 19, "pflanze": "Berg-/Kalk-Aster (Aster amellus)", "sektor": 9}}, "11": {"king_wen": 11, "name": "Der Friede", "titel_quelle": "11. TAI / DER FRIEDE", "zeichen": "☷☰", "binaer_oben_nach_unten": "000111", "oben": "Erde", "unten": "Himmel", "bild_trigramme": "Erde über Himmel", "urteil": "Der Friede. Das Klein geht hin, das Große kommt her.\nHeil! Gelingen!", "bild": "Himmel und Erde vereinigen sich: das Bild des Friedens.\nSo teilt und vollendet der Herrscher\nden Lauf von Himmel und Erde,\nfördert und ordnet die Gaben von Himmel und Erde\nuns steht so dem Volke bei.", "quelle": {"url": "https://projekt-gutenberg.org/authors/richard-wilhelm/books/i-ging/chapter/4/", "text": "Richard Wilhelm, I Ging (1924), Projekt Gutenberg-DE"}, "karaoke": {"satz": "A · Tanz der freundlichen Geister", "datei": "lang-a-tanz-der-freundlichen-geister", "strophe": "A3", "zeile": "Die-Ro-se-glüht-im-A-bend-schein", "start": 144, "gesamt_start": 286, "stimme": "Bariton", "melodie": "M", "nr": 9, "pflanze": "Haselwurz (Asarum europaeum)", "sektor": 8}}, "12": {"king_wen": 12, "name": "Die Stockung", "titel_quelle": "12. PI / DIE STOCKUNG", "zeichen": "☰☷", "binaer_oben_nach_unten": "111000", "oben": "Himmel", "unten": "Erde", "bild_trigramme": "Himmel über Erde", "urteil": "Die Stockung.\nSchlechte Menschen sind nicht fördernd\nfür die Beharrlichkeit des Edlen.\nDas Große geht hin, das Kleine kommt herbei.", "bild": "Himmel und Erde vereinigen sich nicht:\ndas Bild der Stockung.\nSo zieht sich der Edle auf seinen inneren Wert zurück,\num den Schwierigkeiten zu entgehen.\nEr läßt sich nicht durch Einkünfte ehren.", "quelle": {"url": "https://projekt-gutenberg.org/authors/richard-wilhelm/books/i-ging/chapter/11/", "text": "Richard Wilhelm, I Ging (1924), Projekt Gutenberg-DE"}, "karaoke": {"satz": "A · Tanz der freundlichen Geister", "datei": "lang-a-tanz-der-freundlichen-geister", "strophe": "A3", "zeile": "und-Frie-de-wird-im-Her-zen-Keim", "start": 168, "gesamt_start": 310, "stimme": "Bariton", "melodie": "S", "nr": 12, "pflanze": "Haselwurz (Asarum europaeum)", "sektor": 40}}, "13": {"king_wen": 13, "name": "Gemeinschaft mit Menschen", "titel_quelle": "13. TUNG JEN / GEMEINSCHAFT MIT MENSCHEN", "zeichen": "☰☲", "binaer_oben_nach_unten": "111101", "oben": "Himmel", "unten": "Feuer", "bild_trigramme": "Himmel über Feuer", "urteil": "Gemeinschaft mit Menschen im Freien: Gelingen.\nFördernd ist es, das große Wasser zu durchqueren.\nFördernd ist des Edlen Beharrlichkeit.", "bild": "Himmel zusammen mit Feuer:\ndas Bild der Gemeinschaft mit Menschen.\nSo gliedert der Edle die Stämme und unterscheidet die Dinge.", "quelle": {"url": "https://projekt-gutenberg.org/authors/richard-wilhelm/books/i-ging/chapter/51/", "text": "Richard Wilhelm, I Ging (1924), Projekt Gutenberg-DE"}, "karaoke": {"satz": "C · I Ging", "datei": "lang-c-i-ging", "strophe": "CR", "zeile": "aus-Licht-und-Schat-ten-wird-ein-Tanz", "start": 344, "gesamt_start": 1230, "stimme": "Frau", "melodie": "S", "nr": 38, "pflanze": "Kartäuser-Nelke (Dianthus carthusianorum)", "sektor": 17}}, "14": {"king_wen": 14, "name": "Der Besitz von Großem", "titel_quelle": "14. DA YU / DER BESITZ VON GROSSEM", "zeichen": "☲☰", "binaer_oben_nach_unten": "101111", "oben": "Feuer", "unten": "Himmel", "bild_trigramme": "Feuer über Himmel", "urteil": "Der Besitz von Großem: Erhabenes Gelingen.", "bild": "Das Feuer am Himmel oben:\ndas Bild des Besitzes von Großem.\nSo hemmt der Edle das Böse und fördert das Gute\nund gehorcht so des Himmels gutem Willen.", "quelle": {"url": "https://projekt-gutenberg.org/authors/richard-wilhelm/books/i-ging/chapter/9/", "text": "Richard Wilhelm, I Ging (1924), Projekt Gutenberg-DE"}, "karaoke": {"satz": "C · I Ging", "datei": "lang-c-i-ging", "strophe": "C1", "zeile": "Im-Sü-den-steht-das-hel-le-Licht", "start": 48, "gesamt_start": 934, "stimme": "Frau", "melodie": "M", "nr": 25, "pflanze": "Kartäuser-Nelke (Dianthus carthusianorum)", "sektor": 3}}, "15": {"king_wen": 15, "name": "Die Bescheidenheit", "titel_quelle": "15. KIEN / DIE BESCHEIDENHEIT", "zeichen": "☷☶", "binaer_oben_nach_unten": "000100", "oben": "Erde", "unten": "Berg", "bild_trigramme": "Erde über Berg", "urteil": "Bescheidenheit schafft Gelingen.\nDer Edle bringt zu Ende.", "bild": "Inmitten der Erde ist ein Berg:\ndas Bild der Bescheidenheit.\nSo verringert der Edle, was zu viel ist,\nund vermehrt, was zu wenig ist.\nEr wägt die Dinge und macht sie gleich.", "quelle": {"url": "https://projekt-gutenberg.org/authors/richard-wilhelm/books/i-ging/chapter/36/", "text": "Richard Wilhelm, I Ging (1924), Projekt Gutenberg-DE"}, "karaoke": {"satz": "A · Tanz der freundlichen Geister", "datei": "lang-a-tanz-der-freundlichen-geister", "strophe": "A4", "zeile": "O-Herr, der-Ne-bel, Wald-und-Stein", "start": 240, "gesamt_start": 382, "stimme": "Bariton", "melodie": "M", "nr": 13, "pflanze": "Dach-Hauswurz (Sempervivum tectorum)", "sektor": 41}}, "16": {"king_wen": 16, "name": "Die Begeisterung", "titel_quelle": "16. YÜ / DIE BEGEISTERUNG", "zeichen": "☳☷", "binaer_oben_nach_unten": "001000", "oben": "Donner", "unten": "Erde", "bild_trigramme": "Donner über Erde", "urteil": "Die Begeisterung. Fördernd ist es,\nGehilfen einzusetzen und Heere marschieren zu lassen.", "bild": "Der Donner kommt aus der Erde hervorgetönt:\ndas Bild der Begeisterung.\nSo machten die alten Könige Musik,\num die Verdienste zu ehren,\nund brachten sie herrlich dem höchsten Gotte dar,\nindem sie ihre Ahnen dazu einluden.", "quelle": {"url": "https://projekt-gutenberg.org/authors/richard-wilhelm/books/i-ging/chapter/13/", "text": "Richard Wilhelm, I Ging (1924), Projekt Gutenberg-DE"}, "karaoke": {"satz": "C · I Ging", "datei": "lang-c-i-ging", "strophe": "C2", "zeile": "Im-Nor-den-wohnt-der-Schat-ten-mild", "start": 240, "gesamt_start": 1126, "stimme": "Frau", "melodie": "M", "nr": 33, "pflanze": "Küchenschelle (Pulsatilla vulgaris)", "sektor": 37}}, "17": {"king_wen": 17, "name": "Die Nachfolge", "titel_quelle": "17. SUI / DIE NACHFOLGE", "zeichen": "☱☳", "binaer_oben_nach_unten": "011001", "oben": "See", "unten": "Donner", "bild_trigramme": "See über Donner", "urteil": "Die Nachfolge hat erhabenes Gelingen.\nFördernd ist Beharrlichkeit. Kein Makel.", "bild": "Inmitten des Sees ist der Donner: das\nBild der Nachfolge. So kehrt der Edle zur Zeit des\nAbenddunkels zu Erholung und Ruhe ein.", "quelle": {"url": "https://projekt-gutenberg.org/authors/richard-wilhelm/books/i-ging/chapter/26/", "text": "Richard Wilhelm, I Ging (1924), Projekt Gutenberg-DE"}, "karaoke": {"satz": "A · Tanz der freundlichen Geister", "datei": "lang-a-tanz-der-freundlichen-geister", "strophe": "A3", "zeile": "der-Teich-hüllt-Mond-und-Ster-ne-ein", "start": 152, "gesamt_start": 294, "stimme": "Bariton", "melodie": "S", "nr": 10, "pflanze": "Sibirische Schwertlilie (Iris sibirica)", "sektor": 26}}, "18": {"king_wen": 18, "name": "Die Arbeit am Verdorbenen", "titel_quelle": "18. GU / DIE ARBEIT AM VERDORBENEN", "zeichen": "☶☴", "binaer_oben_nach_unten": "100110", "oben": "Berg", "unten": "Wind", "bild_trigramme": "Berg über Wind", "urteil": "Die Arbeit am Verdorbenen hat erhabenes Gelingen.\nFördernd ist es, das große Wasser zu durchqueren.\nVor dem Anfangspunkt drei Tage,\nnach dem Anfangspunkt drei Tage.", "bild": "Unten am Berg weht der Wind: das Bild des Verderbens.\nSo rüttelt der Edle die Leute auf und stärkt ihren Geist.", "quelle": {"url": "https://projekt-gutenberg.org/authors/richard-wilhelm/books/i-ging/chapter/47/", "text": "Richard Wilhelm, I Ging (1924), Projekt Gutenberg-DE"}, "karaoke": {"satz": "A · Tanz der freundlichen Geister", "datei": "lang-a-tanz-der-freundlichen-geister", "strophe": "A", "zeile": "Im-Ne-bel-tan-zen-Geis-ter-leis", "start": 48, "gesamt_start": 190, "stimme": "Bariton", "melodie": "M", "nr": 1, "pflanze": "Dach-Hauswurz (Sempervivum tectorum)", "sektor": 58}}, "19": {"king_wen": 19, "name": "Die Annäherung", "titel_quelle": "19. LIN / DIE ANNÄHERUNG", "zeichen": "☷☱", "binaer_oben_nach_unten": "000011", "oben": "Erde", "unten": "See", "bild_trigramme": "Erde über See", "urteil": "Die Annäherung hat erhabenes Gelingen.\nFördernd ist Beharrlichkeit.\nKommt der achte Monat, so gibt's Unheil.", "bild": "Oberhalb des Sees ist die Erde: das Bild der Annäherung.\nSo ist der Edle in seiner Absicht zu lehren unerschöpflich\nund im Ertragen und Schützen des Volkes ohne Grenzen.", "quelle": {"url": "https://projekt-gutenberg.org/authors/richard-wilhelm/books/i-ging/chapter/60/", "text": "Richard Wilhelm, I Ging (1924), Projekt Gutenberg-DE"}, "karaoke": {"satz": "Finale · Vollendung", "datei": "lang-f-vollendung", "strophe": "F2", "zeile": "Voll-en-det-ist-der-Kreis, der-Ring", "start": 208, "gesamt_start": 1846, "stimme": "beide", "melodie": "M", "nr": 61, "pflanze": "Haselwurz (Asarum europaeum)", "sektor": 16}}, "20": {"king_wen": 20, "name": "Die Betrachtung", "titel_quelle": "20. GUAN / DIE BETRACHTUNG (DER ANBLICK)", "zeichen": "☴☷", "binaer_oben_nach_unten": "110000", "oben": "Wind", "unten": "Erde", "bild_trigramme": "Wind über Erde", "urteil": "Die Betrachtung.\nDie Waschung ist geschehen, aber noch nicht die Darbringung.\nVertrauensvoll blicken sie zu ihm auf.", "bild": "Der Wind geht über die Erde hin:\ndas Bild der Betrachtung.\nSo besuchten die alten Könige die Weltgegenden,\nbetrachteten das Volk und spendeten Belehrung.", "quelle": {"url": "https://projekt-gutenberg.org/authors/richard-wilhelm/books/i-ging/chapter/16/", "text": "Richard Wilhelm, I Ging (1924), Projekt Gutenberg-DE"}, "karaoke": {"satz": "C · I Ging", "datei": "lang-c-i-ging", "strophe": "C2", "zeile": "was-dun-kel-ist, wird-bald-zum-Keim", "start": 256, "gesamt_start": 1142, "stimme": "Frau", "melodie": "M", "nr": 35, "pflanze": "Haselwurz (Asarum europaeum)", "sektor": 36}}, "21": {"king_wen": 21, "name": "Das Durchbeißen", "titel_quelle": "21. SCHI HO / DAS DURCHBEIßEN", "zeichen": "☲☳", "binaer_oben_nach_unten": "101001", "oben": "Feuer", "unten": "Donner", "bild_trigramme": "Feuer über Donner", "urteil": "Das Durchbeißen hat Gelingen.\nFördernd ist es, Gericht walten zu lassen.", "bild": "Donner und Blitz: das Bild des Durchbeißens.\nSo festigten die früheren Könige\ndie Gesetze durch klarbestimmte Strafen.", "quelle": {"url": "https://projekt-gutenberg.org/authors/richard-wilhelm/books/i-ging/chapter/25/", "text": "Richard Wilhelm, I Ging (1924), Projekt Gutenberg-DE"}, "karaoke": {"satz": "D · Begegnung", "datei": "lang-d-begegnung", "strophe": "D2", "zeile": "von-au-ßen-weit-nach-in-nen-still", "start": 304, "gesamt_start": 1568, "stimme": "beide", "melodie": "M", "nr": 53, "pflanze": "Kartäuser-Nelke (Dianthus carthusianorum)", "sektor": 27}}, "22": {"king_wen": 22, "name": "Die Anmut", "titel_quelle": "22. BI / DIE ANMUT", "zeichen": "☶☲", "binaer_oben_nach_unten": "100101", "oben": "Berg", "unten": "Feuer", "bild_trigramme": "Berg über Feuer", "urteil": "Anmut hat Gelingen.\nIm Kleinen ist es fördernd, etwas zu unternehmen.", "bild": "Unten am Berg ist das Feuer: das Bild der Anmut.\nSo verfährt der Edle bei der Klarstellung\nder laufenden Angelegenheiten,\naber er wagt es nicht, danach Streitfragen zu entscheiden.", "quelle": {"url": "https://projekt-gutenberg.org/authors/richard-wilhelm/books/i-ging/chapter/55/", "text": "Richard Wilhelm, I Ging (1924), Projekt Gutenberg-DE"}, "karaoke": {"satz": "D · Begegnung", "datei": "lang-d-begegnung", "strophe": "D2", "zeile": "die-Rin-ge-sind-sich-al-le-gleich", "start": 296, "gesamt_start": 1560, "stimme": "beide", "melodie": "S", "nr": 52, "pflanze": "Kartäuser-Nelke (Dianthus carthusianorum)", "sektor": 23}}, "23": {"king_wen": 23, "name": "Die Zersplitterung", "titel_quelle": "23. BO / DIE ZERSPLITTERUNG", "zeichen": "☶☷", "binaer_oben_nach_unten": "100000", "oben": "Berg", "unten": "Erde", "bild_trigramme": "Berg über Erde", "urteil": "Die Zersplitterung. Nicht fördernd ist es, wohin zu gehen.", "bild": "Der Berg ruht auf der Erde: das Bild der Zersplitterung.\nSo können die Oberen nur durch reiches Spenden an die\nUnteren ihre Stellung sichern.", "quelle": {"url": "https://projekt-gutenberg.org/authors/richard-wilhelm/books/i-ging/chapter/15/", "text": "Richard Wilhelm, I Ging (1924), Projekt Gutenberg-DE"}, "karaoke": {"satz": "Finale · Vollendung", "datei": "lang-f-vollendung", "strophe": "F0", "zeile": "der-Grund-stein, der-im-Was-ser-spricht", "start": 8, "gesamt_start": 1646, "stimme": "beide", "melodie": "F", "nr": 56, "pflanze": "Haselwurz (Asarum europaeum)", "sektor": 34}}, "24": {"king_wen": 24, "name": "Die Wiederkehr", "titel_quelle": "24. FU / DIE WIEDERKEHRT (DIE WENDEZEIT)", "zeichen": "☷☳", "binaer_oben_nach_unten": "000001", "oben": "Erde", "unten": "Donner", "bild_trigramme": "Erde über Donner", "urteil": "Die Wiederkehr. Gelingen.\nAusgang und Eingang ohne Fehl.\nFreunde kommen ohne Makel.\nHin und her geht der Weg.\nAm siebten Tage kommt die Wiederkehr.\nFördernd ist es, zu haben, wohin man geht.", "bild": "Der Donner inmitten der Erde: das Bild der Wendezeit.\nSo schlossen die alten Könige zur Sonnwendzeit die Pässe.\nHändler und Fremdlinge wanderten nicht,\nund der Herrscher bereiste nicht die Gegenden.", "quelle": {"url": "https://projekt-gutenberg.org/authors/richard-wilhelm/books/i-ging/chapter/20/", "text": "Richard Wilhelm, I Ging (1924), Projekt Gutenberg-DE"}, "karaoke": {"satz": "C · I Ging", "datei": "lang-c-i-ging", "strophe": "C2", "zeile": "die-Wie-der-kehr-ruft-al-les-heim", "start": 264, "gesamt_start": 1150, "stimme": "Frau", "melodie": "F", "nr": 36, "pflanze": "Küchenschelle (Pulsatilla vulgaris)", "sektor": 32}}, "25": {"king_wen": 25, "name": "Die Unschuld", "titel_quelle": "25. WU WANG / DIE UNSCHULD (DAS UNERWARTETE)", "zeichen": "☰☳", "binaer_oben_nach_unten": "111001", "oben": "Himmel", "unten": "Donner", "bild_trigramme": "Himmel über Donner", "urteil": "Die Unschuld. Erhabenes Gelingen.\nFördernd ist Beharrlichkeit.\nWenn jemand nicht recht ist, so hat er Unglück,\nund nicht fördernd ist es, irgend etwas zu unternehmen.", "bild": "Unter dem Himmel geht der Donner:\nAlle Dinge erlangen den Naturzustand der Unschuld.\nSo pflegten und nährten die alten Könige,\nreich an Tugend und entsprechend der Zeit, alle Wesen.", "quelle": {"url": "https://projekt-gutenberg.org/authors/richard-wilhelm/books/i-ging/chapter/19/", "text": "Richard Wilhelm, I Ging (1924), Projekt Gutenberg-DE"}, "karaoke": {"satz": "D · Begegnung", "datei": "lang-d-begegnung", "strophe": "D2", "zeile": "der-Hain-hält-A-tem, wie-Gott-will", "start": 312, "gesamt_start": 1576, "stimme": "beide", "melodie": "S", "nr": 54, "pflanze": "Berg-/Kalk-Aster (Aster amellus)", "sektor": 25}}, "26": {"king_wen": 26, "name": "Des Großen Zähmungskraft", "titel_quelle": "26 DA TSCHU / DES GROSSEN ZÄHMUNGSKRAFT", "zeichen": "☶☰", "binaer_oben_nach_unten": "100111", "oben": "Berg", "unten": "Himmel", "bild_trigramme": "Berg über Himmel", "urteil": "Des Großen Zähmungskraft. Fördernd ist\nBeharrlichkeit.\nNicht zu Hause essen bringt Heil.\nFördernd ist es, das große Wasser zu durchqueren.", "bild": "Der Himmel inmitten des Berges:\ndas Bild von des Großen Zähmungskraft.\nSo lernt der Edle viele Worte der Vorzeit\nund Taten der Vergangenheit kennen,\num dadurch seinen Charakter zu festigen.", "quelle": {"url": "https://projekt-gutenberg.org/authors/richard-wilhelm/books/i-ging/chapter/7/", "text": "Richard Wilhelm, I Ging (1924), Projekt Gutenberg-DE"}, "karaoke": {"satz": "A · Tanz der freundlichen Geister", "datei": "lang-a-tanz-der-freundlichen-geister", "strophe": "A", "zeile": "sie-tra-gen-Licht-in-je-de-Hand", "start": 64, "gesamt_start": 206, "stimme": "Bariton", "melodie": "M", "nr": 3, "pflanze": "Dach-Hauswurz (Sempervivum tectorum)", "sektor": 7}}, "27": {"king_wen": 27, "name": "Die Mundwinkel", "titel_quelle": "27. I / DIE MUNDWINKEL (DIE ERNÄHRUNG)", "zeichen": "☶☳", "binaer_oben_nach_unten": "100001", "oben": "Berg", "unten": "Donner", "bild_trigramme": "Berg über Donner", "urteil": "Die Mundwinkel. Beharrlichkeit bringt Heil.\nSieh auf die Ernährung und womit einer selbst sucht\nseinen Mund zu füllen.", "bild": "Unten am Berg ist der Donner: das Bild der Ernährung.\nSo hat der Edle acht auf seine Worte\nund ist mäßig im Essen und Trinken.", "quelle": {"url": "https://projekt-gutenberg.org/authors/richard-wilhelm/books/i-ging/chapter/23/", "text": "Richard Wilhelm, I Ging (1924), Projekt Gutenberg-DE"}, "karaoke": {"satz": "Finale · Vollendung", "datei": "lang-f-vollendung", "strophe": "F0", "zeile": "Bau-mei-ster, leg-den-ers-ten-Stein", "start": 16, "gesamt_start": 1654, "stimme": "beide", "melodie": "M", "nr": 57, "pflanze": "Dach-Hauswurz (Sempervivum tectorum)", "sektor": 31}}, "28": {"king_wen": 28, "name": "Des Großen Übergewicht", "titel_quelle": "28. DA GO / DES GROSSEN ÜBERGEWICHT", "zeichen": "☱☴", "binaer_oben_nach_unten": "011110", "oben": "See", "unten": "Wind", "bild_trigramme": "See über Wind", "urteil": "Des Großen Übergewicht. Der Firstbalken biegt sich durch.\nFördernd ist es, zu haben, wohin man gehe. Gelingen.", "bild": "Der See geht über die Bäume weg:\ndas Bild des Übergewichts im Großen.\nSo ist der Edle, wenn er allein steht, unbesorgt,\nund wenn er auf die Welt verzichten muß, unverzagt.", "quelle": {"url": "https://projekt-gutenberg.org/authors/richard-wilhelm/books/i-ging/chapter/50/", "text": "Richard Wilhelm, I Ging (1924), Projekt Gutenberg-DE"}, "karaoke": {"satz": "B · Spiral Roll-out", "datei": "lang-b-spiral-roll-out", "strophe": "B2", "zeile": "und-schenkt-uns-ei-ne-Stun-de-Glück", "start": 216, "gesamt_start": 730, "stimme": "Bariton", "melodie": "S", "nr": 24, "pflanze": "Sibirische Schwertlilie (Iris sibirica)", "sektor": 63}}, "29": {"king_wen": 29, "name": "Das Abgründige", "titel_quelle": "29. KAN / DAS ABGRÜNDIGE, DAS WASSER", "zeichen": "☵☵", "binaer_oben_nach_unten": "010010", "oben": "Wasser", "unten": "Wasser", "bild_trigramme": "Wasser über Wasser", "urteil": "Das wiederholte Abgründige.\nWenn du wahrhaftig bist, so hast du im Herzen Gelingen,\nund was du tust, hat Erfolg.", "bild": "Das Wasser fließt ununterbrochen und kommt ans Ziel:\ndas Bild des wiederholten Abgründigen.\nSo wandelt der Edle in dauernder Tugend\nund übt das Geschäft des Lehrens.", "quelle": {"url": "https://projekt-gutenberg.org/authors/richard-wilhelm/books/i-ging/chapter/30/", "text": "Richard Wilhelm, I Ging (1924), Projekt Gutenberg-DE"}, "karaoke": {"satz": "C · I Ging", "datei": "lang-c-i-ging", "strophe": "C1", "zeile": "und-Was-ser-hält, was-nie-mand-maß", "start": 72, "gesamt_start": 958, "stimme": "Frau", "melodie": "S", "nr": 28, "pflanze": "Weicher Frauenmantel (Alchemilla mollis)", "sektor": 51}}, "30": {"king_wen": 30, "name": "Das Haftende", "titel_quelle": "30. LI / DAS HAFTENE, DAS FEUER", "zeichen": "☲☲", "binaer_oben_nach_unten": "101101", "oben": "Feuer", "unten": "Feuer", "bild_trigramme": "Feuer über Feuer", "urteil": "Das Haftende. Fördernd ist Beharrlichkeit.\nSie bringt Gelingen. Pflege der Kuh bringt Heil.", "bild": "Die Helle erhebt sich zweimal:\ndas Bild des Feuers.\nSo erleuchtet der große Mann durch Fortsetzung dieser Helle die vier Weltgegenden.", "quelle": {"url": "https://projekt-gutenberg.org/authors/richard-wilhelm/books/i-ging/chapter/57/", "text": "Richard Wilhelm, I Ging (1924), Projekt Gutenberg-DE", "hinweis": "zweite Bildzeile aus dem folgenden Absatz der Quelle ergänzt (Satzanfang „So …“)"}, "karaoke": {"satz": "Finale · Vollendung", "datei": "lang-f-vollendung", "strophe": "F1", "zeile": "aus-Ro-sen, Was-ser, Licht-und-Stein", "start": 160, "gesamt_start": 1798, "stimme": "beide", "melodie": "M", "nr": 60, "pflanze": "Kartäuser-Nelke (Dianthus carthusianorum)", "sektor": 19}}, "31": {"king_wen": 31, "name": "Die Einwirkung", "titel_quelle": "31. HIEN / DIE EINWIRKUNG, DIE WERBUNG", "zeichen": "☱☶", "binaer_oben_nach_unten": "011100", "oben": "See", "unten": "Berg", "bild_trigramme": "See über Berg", "urteil": "Die Einwirkung. Gelingen.\nFördernd ist Beharrlichkeit.\nEin Mädchen nehmen bringt Heil.", "bild": "Auf dem Berge ist ein See:\ndas Bild der Einwirkung.\nSo läßt der Edle durch Aufnahmebereitschaft die\nMenschen an sich herankommen.", "quelle": {"url": "https://projekt-gutenberg.org/authors/richard-wilhelm/books/i-ging/chapter/42/", "text": "Richard Wilhelm, I Ging (1924), Projekt Gutenberg-DE"}, "karaoke": {"satz": "A · Tanz der freundlichen Geister", "datei": "lang-a-tanz-der-freundlichen-geister", "strophe": "A4", "zeile": "du-lässt-die-Alb-ge-seg-net-sein", "start": 248, "gesamt_start": 390, "stimme": "Bariton", "melodie": "S", "nr": 14, "pflanze": "Dach-Hauswurz (Sempervivum tectorum)", "sektor": 47}}, "32": {"king_wen": 32, "name": "Die Dauer", "titel_quelle": "32. HONG / DIE DAUER", "zeichen": "☳☴", "binaer_oben_nach_unten": "001110", "oben": "Donner", "unten": "Wind", "bild_trigramme": "Donner über Wind", "urteil": "Gelingen. Kein Makel.\nFördernd ist Beharrlichkeit.\nFördernd ist, zu haben, wohin man gehe.", "bild": "Donner und Wind: das Bild der Dauer.\nSo steht der Edle fest und wandelt seine Richtung nicht.", "quelle": {"url": "https://projekt-gutenberg.org/authors/richard-wilhelm/books/i-ging/chapter/45/", "text": "Richard Wilhelm, I Ging (1924), Projekt Gutenberg-DE"}, "karaoke": {"satz": "B · Spiral Roll-out", "datei": "lang-b-spiral-roll-out", "strophe": "B2", "zeile": "Tick, tack, die-Uhr-dreht-sich-zu-rück", "start": 208, "gesamt_start": 722, "stimme": "Bariton", "melodie": "M", "nr": 23, "pflanze": "Küchenschelle (Pulsatilla vulgaris)", "sektor": 61}}, "33": {"king_wen": 33, "name": "Der Rückzug", "titel_quelle": "33. DUN / DER RÜCKZUG", "zeichen": "☰☶", "binaer_oben_nach_unten": "111100", "oben": "Himmel", "unten": "Berg", "bild_trigramme": "Himmel über Berg", "urteil": "Der Rückzug. Gelingen. Im Kleinen ist fördernd Beharrlichkeit.", "bild": "Unter dem Himmel ist der Berg: das Bild des Rückzugs.\nSo hält der Edle den Gemeinen fern,\nnicht zornig, sondern gemessen.", "quelle": {"url": "https://projekt-gutenberg.org/authors/richard-wilhelm/books/i-ging/chapter/35/", "text": "Richard Wilhelm, I Ging (1924), Projekt Gutenberg-DE"}, "karaoke": {"satz": "D · Begegnung", "datei": "lang-d-begegnung", "strophe": "D0", "zeile": "der-Herr-führt-uns-von-fern-her-bei", "start": 64, "gesamt_start": 1328, "stimme": "beide", "melodie": "M", "nr": 41, "pflanze": "Berg-/Kalk-Aster (Aster amellus)", "sektor": 48}}, "34": {"king_wen": 34, "name": "Des Großen Macht", "titel_quelle": "34. DA DSCHUANG / DES GROSSEN MACHT", "zeichen": "☳☰", "binaer_oben_nach_unten": "001111", "oben": "Donner", "unten": "Himmel", "bild_trigramme": "Donner über Himmel", "urteil": "Des Großen Macht. Fördernd ist Beharrlichkeit", "bild": "Der Donner ist am Himmel droben:\ndas Bild der Macht des Großen.\nSo tritt der Edle nicht auf Wege,\ndie nicht der Ordnung entsprechen.", "quelle": {"url": "https://projekt-gutenberg.org/authors/richard-wilhelm/books/i-ging/chapter/5/", "text": "Richard Wilhelm, I Ging (1924), Projekt Gutenberg-DE"}, "karaoke": {"satz": "B · Spiral Roll-out", "datei": "lang-b-spiral-roll-out", "strophe": "B1", "zeile": "Tick, tack, die-Uhr-dreht-sich-zu-rück", "start": 96, "gesamt_start": 610, "stimme": "Bariton", "melodie": "M", "nr": 17, "pflanze": "Küchenschelle (Pulsatilla vulgaris)", "sektor": 4}}, "35": {"king_wen": 35, "name": "Der Fortschritt", "titel_quelle": "35. DSIN / DER FORTSCHRITT", "zeichen": "☲☷", "binaer_oben_nach_unten": "101000", "oben": "Feuer", "unten": "Erde", "bild_trigramme": "Feuer über Erde", "urteil": "Der Fortschritt:\nDer starke Fürst wird geehrt durch Pferde in großer Menge.\nAn einem Tage wird er dreimal empfangen", "bild": "Die Sonne steigt über die Erde empor:\ndas Bild des Fortschritts.\nSo macht der Edle selbst seine klaren Anlagen hell.", "quelle": {"url": "https://projekt-gutenberg.org/authors/richard-wilhelm/books/i-ging/chapter/17/", "text": "Richard Wilhelm, I Ging (1924), Projekt Gutenberg-DE"}, "karaoke": {"satz": "C · I Ging", "datei": "lang-c-i-ging", "strophe": "C0", "zeile": "die-Sa-men-aus-der-lan-gen-Nacht", "start": 128, "gesamt_start": 1014, "stimme": "Frau", "melodie": "S", "nr": 30, "pflanze": "Haselwurz (Asarum europaeum)", "sektor": 38}}, "36": {"king_wen": 36, "name": "Die Verfinsterung des Lichts", "titel_quelle": "36. MING / DIE VERFINSTERUNG DES LICHTS", "zeichen": "☷☲", "binaer_oben_nach_unten": "000101", "oben": "Erde", "unten": "Feuer", "bild_trigramme": "Erde über Feuer", "urteil": "Die Verfinsterung des Lichts.\nFördernd ist es, in der Not beharrlich zu sein.", "bild": "Das Licht ist in die Erde hineingesunken:\ndas Bild der Verfinsterung des Lichts.\nSo lebt der Edle mit der großen Menge:\ner verhüllt seinen Schein und bleibt doch hell.", "quelle": {"url": "https://projekt-gutenberg.org/authors/richard-wilhelm/books/i-ging/chapter/52/", "text": "Richard Wilhelm, I Ging (1924), Projekt Gutenberg-DE"}, "karaoke": {"satz": "D · Begegnung", "datei": "lang-d-begegnung", "strophe": "D1", "zeile": "ein-Lied, ein-Licht, ein-Grund, ein-Sein", "start": 248, "gesamt_start": 1512, "stimme": "Frau", "melodie": "S", "nr": 50, "pflanze": "Kartäuser-Nelke (Dianthus carthusianorum)", "sektor": 24}}, "37": {"king_wen": 37, "name": "Die Sippe", "titel_quelle": "37. GIA JEN / DIE SIPPE", "zeichen": "☴☲", "binaer_oben_nach_unten": "110101", "oben": "Wind", "unten": "Feuer", "bild_trigramme": "Wind über Feuer", "urteil": "Die Sippe. Fördernd ist die Beharrlichkeit der Frau.", "bild": "Der Wind kommt aus dem Feuer hervor:\ndas Bild der Sippe.\nSo hat der Edle in seinen Worten die Sache\nund in seinem Wandel die Dauer.", "quelle": {"url": "https://projekt-gutenberg.org/authors/richard-wilhelm/books/i-ging/chapter/56/", "text": "Richard Wilhelm, I Ging (1924), Projekt Gutenberg-DE"}, "karaoke": {"satz": "A · Tanz der freundlichen Geister", "datei": "lang-a-tanz-der-freundlichen-geister", "strophe": "A3", "zeile": "die-Geis-ter-keh-ren-lä-chelnd-heim", "start": 160, "gesamt_start": 302, "stimme": "Bariton", "melodie": "M", "nr": 11, "pflanze": "Echtes Federgras (Stipa pennata)", "sektor": 21}}, "38": {"king_wen": 38, "name": "Der Gegensatz", "titel_quelle": "38. KUI / DER GEGENSATZ", "zeichen": "☲☱", "binaer_oben_nach_unten": "101011", "oben": "Feuer", "unten": "See", "bild_trigramme": "Feuer über See", "urteil": "Der Gegensatz\nIn kleinen Sachen Heil!", "bild": "Oben das Feuer, unten der See:\ndas Bild des Gegensatzes.\nSo behält der Edle bei aller Gemeinschaft seine Besonderheit.", "quelle": {"url": "https://projekt-gutenberg.org/authors/richard-wilhelm/books/i-ging/chapter/65/", "text": "Richard Wilhelm, I Ging (1924), Projekt Gutenberg-DE"}, "karaoke": {"satz": "Finale · Vollendung", "datei": "lang-f-vollendung", "strophe": "F2", "zeile": "der-Teich, das-Licht, die-Ro-se, du", "start": 224, "gesamt_start": 1862, "stimme": "beide", "melodie": "M", "nr": 63, "pflanze": "Kartäuser-Nelke (Dianthus carthusianorum)", "sektor": 11}}, "39": {"king_wen": 39, "name": "Das Hemmnis", "titel_quelle": "39. GIEN / DAS HEMMNIS", "zeichen": "☵☶", "binaer_oben_nach_unten": "010100", "oben": "Wasser", "unten": "Berg", "bild_trigramme": "Wasser über Berg", "urteil": "Das Hemmnis. Fördernd ist der Südwesten.\nNicht fördernd ist der Nordosten.\nFördernd ist es, den großen Mann zu sehen.\nBeharrlichkeit ist von Heil.", "bild": "Auf dem Berg ist das Wasser: das Bild des Hemmnisses.\nSo wendet sich der Edle seiner eigenen Person zu\nund bildet seinen Charakter.", "quelle": {"url": "https://projekt-gutenberg.org/authors/richard-wilhelm/books/i-ging/chapter/38/", "text": "Richard Wilhelm, I Ging (1924), Projekt Gutenberg-DE"}, "karaoke": {"satz": "A · Tanz der freundlichen Geister", "datei": "lang-a-tanz-der-freundlichen-geister", "strophe": "A", "zeile": "und-seg-nen-still-das-Al-ben-land", "start": 72, "gesamt_start": 214, "stimme": "Bariton", "melodie": "S", "nr": 4, "pflanze": "Dach-Hauswurz (Sempervivum tectorum)", "sektor": 43}}, "40": {"king_wen": 40, "name": "Die Befreiung", "titel_quelle": "40. HIE / DIE BEFREIUNG", "zeichen": "☳☵", "binaer_oben_nach_unten": "001010", "oben": "Donner", "unten": "Wasser", "bild_trigramme": "Donner über Wasser", "urteil": "Die Befreiung. Fördernd ist der Südwesten.\nWenn nichts mehr da ist, wohin man zu gehen hätte,\nist das Wiederkommen von Heil.\nWenn es noch etwas gibt, wohin man gehen muß,\ndann ist Raschheit von Heil.", "bild": "Donner und Regen erheben sich:\ndas Bild der Befreiung.\nSo verzeiht der Edle Fehler und vergibt die Schuld.", "quelle": {"url": "https://projekt-gutenberg.org/authors/richard-wilhelm/books/i-ging/chapter/29/", "text": "Richard Wilhelm, I Ging (1924), Projekt Gutenberg-DE"}, "karaoke": {"satz": "A · Tanz der freundlichen Geister", "datei": "lang-a-tanz-der-freundlichen-geister", "strophe": "A4", "zeile": "ver-lass-den-Ro-sen-gar-ten-nicht", "start": 264, "gesamt_start": 406, "stimme": "Bariton", "melodie": "S", "nr": 16, "pflanze": "Weicher Frauenmantel (Alchemilla mollis)", "sektor": 53}}, "41": {"king_wen": 41, "name": "Die Minderung", "titel_quelle": "41. SUN / DIE MINDERUNG", "zeichen": "☶☱", "binaer_oben_nach_unten": "100011", "oben": "Berg", "unten": "See", "bild_trigramme": "Berg über See", "urteil": "Minderung verbunden mit\nWahrhaftigkeit wirkt erhabenes Heil ohne Makel.\nMan kann darin beharrlich sein.\nFördernd ist es, etwas zu unternehmen.\nWie übt man das aus?\nZwei kleine Schüsselchen mag man benützen zum Opfer.", "bild": "Unten am Berg ist der See: das Bild der Minderung.\nSo bändigt der Edle seinen Zorn und hemmt seine Triebe.", "quelle": {"url": "https://projekt-gutenberg.org/authors/richard-wilhelm/books/i-ging/chapter/63/", "text": "Richard Wilhelm, I Ging (1924), Projekt Gutenberg-DE"}, "karaoke": {"satz": "A · Tanz der freundlichen Geister", "datei": "lang-a-tanz-der-freundlichen-geister", "strophe": "A", "zeile": "um-Ro-sen, Teich-und-Hü-gel-kreis", "start": 56, "gesamt_start": 198, "stimme": "Bariton", "melodie": "S", "nr": 2, "pflanze": "Sibirische Schwertlilie (Iris sibirica)", "sektor": 15}}, "42": {"king_wen": 42, "name": "Die Mehrung", "titel_quelle": "42 I. / DIE MEHRUNG", "zeichen": "☴☳", "binaer_oben_nach_unten": "110001", "oben": "Wind", "unten": "Donner", "bild_trigramme": "Wind über Donner", "urteil": "Die Mehrung. Fördernd ist es, etwas zu unternehmen.\nFördernd ist es, das große Wasser zu durchqueren.", "bild": "Wind und Donner: das Bild der Mehrung.\nSo der Edle: Sieht er Gutes, so ahmt er es nach,\nhat er Fehler, so legt er sie ab.", "quelle": {"url": "https://projekt-gutenberg.org/authors/richard-wilhelm/books/i-ging/chapter/24/", "text": "Richard Wilhelm, I Ging (1924), Projekt Gutenberg-DE"}, "karaoke": {"satz": "C · I Ging", "datei": "lang-c-i-ging", "strophe": "C1", "zeile": "sechs-Li-ni-en, die-Stil-le-spricht", "start": 56, "gesamt_start": 942, "stimme": "Frau", "melodie": "S", "nr": 26, "pflanze": "Echtes Federgras (Stipa pennata)", "sektor": 29}}, "43": {"king_wen": 43, "name": "Der Durchbruch", "titel_quelle": "43. GUAI / DER DURCHBRUCH (Die Entschlossenheit)", "zeichen": "☱☰", "binaer_oben_nach_unten": "011111", "oben": "See", "unten": "Himmel", "bild_trigramme": "See über Himmel", "urteil": "Der Durchbruch.\nEntschlossen muß man am Hof des Königs\ndie Sache bekanntmachen.\nDer Wahrheit gemäß muß sie verkündet werden. Gefahr !\nMan muß seine eigene Stadt benachrichtigen.\nNicht fördernd ist es, zu den Waffen zu greifen.\nFördernd ist es, etwas zu unternehmen.", "bild": "Der See ist an den Himmel emporgestiegen:\ndas Bild des Durchbruchs.\nSo spendet der Edle Reichtum nach unten hin\nund scheut es, bei seiner Tugend zu verweilen.", "quelle": {"url": "https://projekt-gutenberg.org/authors/richard-wilhelm/books/i-ging/chapter/10/", "text": "Richard Wilhelm, I Ging (1924), Projekt Gutenberg-DE"}, "karaoke": {"satz": "A · Tanz der freundlichen Geister", "datei": "lang-a-tanz-der-freundlichen-geister", "strophe": "A", "zeile": "der-Tanz-wird-Lob, der-Kreis-wird-weit", "start": 104, "gesamt_start": 246, "stimme": "Bariton", "melodie": "S", "nr": 8, "pflanze": "Berg-/Kalk-Aster (Aster amellus)", "sektor": 2}}, "44": {"king_wen": 44, "name": "Das Entgegenkommen", "titel_quelle": "44. GOU / DAS ENTGEGENKOMMEN", "zeichen": "☰☴", "binaer_oben_nach_unten": "111110", "oben": "Himmel", "unten": "Wind", "bild_trigramme": "Himmel über Wind", "urteil": "Das Entgegenkommen. Das Mädchen ist mächtig.\nMan soll ein solches Mädchen nicht heiraten.", "bild": "Unter dem Himmel ist der Wind:\ndas Bild des Entgegenkommens.\nSo macht es der Fürst beim Verbreiten seiner Befehle\nund ihrer Verkündigung an die vier Himmelsgegenden.", "quelle": {"url": "https://projekt-gutenberg.org/authors/richard-wilhelm/books/i-ging/chapter/43/", "text": "Richard Wilhelm, I Ging (1924), Projekt Gutenberg-DE"}, "karaoke": {"satz": "C · I Ging", "datei": "lang-c-i-ging", "strophe": "C0", "zeile": "Im-Os-ten-weckt-der-Don-ner-sacht", "start": 120, "gesamt_start": 1006, "stimme": "Frau", "melodie": "M", "nr": 29, "pflanze": "Berg-/Kalk-Aster (Aster amellus)", "sektor": 64}}, "45": {"king_wen": 45, "name": "Die Sammlung", "titel_quelle": "45. TSUI / DIE SAMMLUNG", "zeichen": "☱☷", "binaer_oben_nach_unten": "011000", "oben": "See", "unten": "Erde", "bild_trigramme": "See über Erde", "urteil": "Die Sammlung. Gelingen.\nDer König naht sich seinem Tempel.\nFördernd ist es, den großen Mann zu sehen.\nDas bringt Gelingen. Fördernd ist Beharrlichkeit.\nGroße Opfer zu bringen schafft Heil.\nFördernd ist es, etwas zu unternehmen.", "bild": "Der See ist oberhalb der Erde:\ndas Bild der Sammlung.\nSo erneuert der Edle seine Waffen,\num Unvorhergesehenem zu begegnen.", "quelle": {"url": "https://projekt-gutenberg.org/authors/richard-wilhelm/books/i-ging/chapter/18/", "text": "Richard Wilhelm, I Ging (1924), Projekt Gutenberg-DE"}, "karaoke": {"satz": "D · Begegnung", "datei": "lang-d-begegnung", "strophe": "D0", "zeile": "Drei-Rin-ge-um-den-stil-len-Teich", "start": 48, "gesamt_start": 1312, "stimme": "beide", "melodie": "M", "nr": 39, "pflanze": "Sibirische Schwertlilie (Iris sibirica)", "sektor": 39}}, "46": {"king_wen": 46, "name": "Das Empordringen", "titel_quelle": "46. SCHONG / DAS EMPORDRINGEN", "zeichen": "☷☴", "binaer_oben_nach_unten": "000110", "oben": "Erde", "unten": "Wind", "bild_trigramme": "Erde über Wind", "urteil": "Das Empordringen hat erhabenes Gelingen.\nMan muß den großen Mann sehen.\nFürchte dich nicht!\nAufbruch nach Süden bringt Heil.", "bild": "Inmitten der Erde wächst das Holz:\ndas Bild des Empordringens.\nSo häuft der Edle hingebenden Wesens Kleines,\num es zu Hohem und Großem zu bringen.", "quelle": {"url": "https://projekt-gutenberg.org/authors/richard-wilhelm/books/i-ging/chapter/44/", "text": "Richard Wilhelm, I Ging (1924), Projekt Gutenberg-DE"}, "karaoke": {"satz": "C · I Ging", "datei": "lang-c-i-ging", "strophe": "C1", "zeile": "der-Wind-geht-sanft-durchs-Fe-der-gras", "start": 64, "gesamt_start": 950, "stimme": "Frau", "melodie": "M", "nr": 27, "pflanze": "Echtes Federgras (Stipa pennata)", "sektor": 57}}, "47": {"king_wen": 47, "name": "Die Bedrängnis", "titel_quelle": "47. KUN / DIE BEDRÄNGNIS (DIE ERSCHÖPFUNG)", "zeichen": "☱☵", "binaer_oben_nach_unten": "011010", "oben": "See", "unten": "Wasser", "bild_trigramme": "See über Wasser", "urteil": "Die Bedrängnis. Gelingen. Beharrlichkeit.\nDer große Mann wirkt Heil. Kein Makel.\nWenn man etwas zu sagen hat, wird es nicht geglaubt.", "bild": "Im See ist kein Wasser: das Bild der Erschöpfung.\nSo setzt der Edle sein Leben daran,\num seinem Willen zu folgen.", "quelle": {"url": "https://projekt-gutenberg.org/authors/richard-wilhelm/books/i-ging/chapter/34/", "text": "Richard Wilhelm, I Ging (1924), Projekt Gutenberg-DE"}, "karaoke": {"satz": "C · I Ging", "datei": "lang-c-i-ging", "strophe": "CR", "zeile": "Ein-Ring-ist-rund, ein-Ring-ist-ganz", "start": 336, "gesamt_start": 1222, "stimme": "Frau", "melodie": "M", "nr": 37, "pflanze": "Sibirische Schwertlilie (Iris sibirica)", "sektor": 55}}, "48": {"king_wen": 48, "name": "Der Brunnen", "titel_quelle": "48. DSING / DER BRUNNEN", "zeichen": "☵☴", "binaer_oben_nach_unten": "010110", "oben": "Wasser", "unten": "Wind", "bild_trigramme": "Wasser über Wind", "urteil": "Der Brunnen. Man mag die Stadt wechseln,\naber kann nicht den Brunnen wechseln.\nEr nimmt nicht ab und nimmt nicht zu.\nSie kommen und gehen und schöpfen aus dem Brunnen.\nWenn man beinahe das Brunnenwasser erreicht hat,\naber noch nicht mit dem Seil drunten ist\noder seinen Krug zerbricht so bringt das Unheil.", "bild": "Über dem Holz ist Wasser: das Bild des Brunnens.\nSo ermuntert der Edle das Volk bei der Arbeit\nund ermahnt es, einander zu helfen.", "quelle": {"url": "https://projekt-gutenberg.org/authors/richard-wilhelm/books/i-ging/chapter/46/", "text": "Richard Wilhelm, I Ging (1924), Projekt Gutenberg-DE"}, "karaoke": {"satz": "B · Spiral Roll-out", "datei": "lang-b-spiral-roll-out", "strophe": "B2", "zeile": "die-Spi-ra-le-hat-uns-ge-packt", "start": 200, "gesamt_start": 714, "stimme": "Bariton", "melodie": "S", "nr": 22, "pflanze": "Echtes Federgras (Stipa pennata)", "sektor": 59}}, "49": {"king_wen": 49, "name": "Die Umwälzung", "titel_quelle": "49. GO / DIE UMWÄLZUNG (DIE MAUSERUNG)", "zeichen": "☱☲", "binaer_oben_nach_unten": "011101", "oben": "See", "unten": "Feuer", "bild_trigramme": "See über Feuer", "urteil": "Die Umwälzung.\nAm eigenen Tag, da findest du Glauben.\nErhabenes Gelingen, fördernd durch Beharrlichkeit.\nDie Reue schwindet.", "bild": "Im See ist Feuer: das Bild der Umwälzung.\nSo ordnet der Edle die Zeitrechnung\nund macht die Zeiten klar.", "quelle": {"url": "https://projekt-gutenberg.org/authors/richard-wilhelm/books/i-ging/chapter/58/", "text": "Richard Wilhelm, I Ging (1924), Projekt Gutenberg-DE"}, "karaoke": {"satz": "D · Begegnung", "datei": "lang-d-begegnung", "strophe": "D1", "zeile": "Am-Teich-wird-aus-den-Stim-men-eins", "start": 240, "gesamt_start": 1504, "stimme": "Bariton", "melodie": "M", "nr": 49, "pflanze": "Sibirische Schwertlilie (Iris sibirica)", "sektor": 18}}, "50": {"king_wen": 50, "name": "Der Tiegel", "titel_quelle": "50. DING / DER TIEGEL", "zeichen": "☲☴", "binaer_oben_nach_unten": "101110", "oben": "Feuer", "unten": "Wind", "bild_trigramme": "Feuer über Wind", "urteil": "Der Tiegel. Erhabenes Heil. Gelingen.", "bild": "Über dem Holz ist Feuer: das Bild des Tiegels.\nSo festigt der Edle\ndurch Richtigmachung der Stellung das Schicksal.", "quelle": {"url": "https://projekt-gutenberg.org/authors/richard-wilhelm/books/i-ging/chapter/49/", "text": "Richard Wilhelm, I Ging (1924), Projekt Gutenberg-DE"}, "karaoke": {"satz": "A · Tanz der freundlichen Geister", "datei": "lang-a-tanz-der-freundlichen-geister", "strophe": "A4", "zeile": "wir-dan-ken-dir-für-Brot-und-Licht", "start": 256, "gesamt_start": 398, "stimme": "Bariton", "melodie": "M", "nr": 15, "pflanze": "Kartäuser-Nelke (Dianthus carthusianorum)", "sektor": 62}}, "51": {"king_wen": 51, "name": "Das Erregende", "titel_quelle": "51. DSCHEN / DAS ERREGENDE\n (DAS ERSCHÜTTERNDE, DER DONNER)", "zeichen": "☳☳", "binaer_oben_nach_unten": "001001", "oben": "Donner", "unten": "Donner", "bild_trigramme": "Donner über Donner", "urteil": "Das Erschüttern bringt Gelingen.\nDas Erschüttern kommt: Hu, Hu !\nLachende Worte: Ha, Ha!\nDas Erschüttern erschreckt hundert Meilen,\nund er laßt nicht Opferlöffel und Kelch fallen.", "bild": "Fortgesetzter Donner: das Bild des Erschütterns.\nSo macht der Edle unter Furcht und Zittern sein\nLeben recht und erforscht sich selbst.", "quelle": {"url": "https://projekt-gutenberg.org/authors/richard-wilhelm/books/i-ging/chapter/21/", "text": "Richard Wilhelm, I Ging (1924), Projekt Gutenberg-DE"}, "karaoke": {"satz": "Finale · Vollendung", "datei": "lang-f-vollendung", "strophe": "F2", "zeile": "zu-dem-die-gan-ze-Schöp-fung-singt", "start": 216, "gesamt_start": 1854, "stimme": "beide", "melodie": "F", "nr": 62, "pflanze": "Küchenschelle (Pulsatilla vulgaris)", "sektor": 28}}, "52": {"king_wen": 52, "name": "Das Stillehalten", "titel_quelle": "52. GEN / DAS STILLEHALTEN, DER BERG", "zeichen": "☶☶", "binaer_oben_nach_unten": "100100", "oben": "Berg", "unten": "Berg", "bild_trigramme": "Berg über Berg", "urteil": "Stillehalten seines Rückens,\nso daß er seinen Leib nicht mehr empfindet.\nEr geht in seinen Hof und sieht nicht seine Menschen.\nKein Makel.", "bild": "Zusammenstehende Berge: das Bild des Stillehaltens.\nSo geht der Edle mit seinen Gedanken nicht über seine Lage hinaus.", "quelle": {"url": "https://projekt-gutenberg.org/authors/richard-wilhelm/books/i-ging/chapter/39/", "text": "Richard Wilhelm, I Ging (1924), Projekt Gutenberg-DE"}, "karaoke": {"satz": "D · Begegnung", "datei": "lang-d-begegnung", "strophe": "D2", "zeile": "Nun-ruht-die-Spi-ra-le-am-Teich", "start": 288, "gesamt_start": 1552, "stimme": "beide", "melodie": "M", "nr": 51, "pflanze": "Dach-Hauswurz (Sempervivum tectorum)", "sektor": 42}}, "53": {"king_wen": 53, "name": "Die Entwicklung", "titel_quelle": "53. DSIEN / DIE ENTWICKLUNG (ALLMÄHLICHER FORTSCHRITT)", "zeichen": "☴☶", "binaer_oben_nach_unten": "110100", "oben": "Wind", "unten": "Berg", "bild_trigramme": "Wind über Berg", "urteil": "Die Entwicklung. Das Mädchen wird\nverheiratet. Heil !\nFördernd ist Beharrlichkeit.", "bild": "Auf dem Berge ist ein Baum das Bild der Entwicklung.\nSo weilt der Edle in würdiger Tugend,\num die Sitten zu bessern.", "quelle": {"url": "https://projekt-gutenberg.org/authors/richard-wilhelm/books/i-ging/chapter/40/", "text": "Richard Wilhelm, I Ging (1924), Projekt Gutenberg-DE"}, "karaoke": {"satz": "D · Begegnung", "datei": "lang-d-begegnung", "strophe": "D1", "zeile": "ich-brin-ge-dir-den-Bam-bus-wind", "start": 216, "gesamt_start": 1480, "stimme": "Frau", "melodie": "S", "nr": 46, "pflanze": "Echtes Federgras (Stipa pennata)", "sektor": 44}}, "54": {"king_wen": 54, "name": "Das heiratende Mädchen", "titel_quelle": "54. GUI ME / DAS HEIRATENDE MÄDCHEN", "zeichen": "☳☱", "binaer_oben_nach_unten": "001011", "oben": "Donner", "unten": "See", "bild_trigramme": "Donner über See", "urteil": "Das heiratende Mädchen.\nUnternehmungen bringen Unheil.\nNichts, das fördernd wäre.", "bild": "Oberhalb des Sees ist der Donner:\ndas Bild des heiratenden Mädchens.\nSo erkennt der Edle durch die Ewigkeit des Endes das Vergängliche.", "quelle": {"url": "https://projekt-gutenberg.org/authors/richard-wilhelm/books/i-ging/chapter/61/", "text": "Richard Wilhelm, I Ging (1924), Projekt Gutenberg-DE"}, "karaoke": {"satz": "D · Begegnung", "datei": "lang-d-begegnung", "strophe": "D1", "zeile": "Wir-spre-chen-fremd-und-doch-ver-traut", "start": 224, "gesamt_start": 1488, "stimme": "Bariton", "melodie": "M", "nr": 47, "pflanze": "Küchenschelle (Pulsatilla vulgaris)", "sektor": 12}}, "55": {"king_wen": 55, "name": "Die Fülle", "titel_quelle": "55. FONG / DIE FÜLLE", "zeichen": "☳☲", "binaer_oben_nach_unten": "001101", "oben": "Donner", "unten": "Feuer", "bild_trigramme": "Donner über Feuer", "urteil": "Die Fülle hat Gelingen.\nDer König erreicht sie.\nSei nicht traurig; du mußt sein wie die Sonne am Mittag.", "bild": "Donner und Blitz kommen beide: das Bild der Fülle.\nSo entscheidet der Edle die Prozesse und führt die Strafen aus.", "quelle": {"url": "https://projekt-gutenberg.org/authors/richard-wilhelm/books/i-ging/chapter/53/", "text": "Richard Wilhelm, I Ging (1924), Projekt Gutenberg-DE"}, "karaoke": {"satz": "C · I Ging", "datei": "lang-c-i-ging", "strophe": "C0", "zeile": "bis-je-des-Zei-chen-Früch-te-bringt", "start": 144, "gesamt_start": 1030, "stimme": "Frau", "melodie": "S", "nr": 32, "pflanze": "Kartäuser-Nelke (Dianthus carthusianorum)", "sektor": 20}}, "56": {"king_wen": 56, "name": "Der Wanderer", "titel_quelle": "56. LÜ / DER WANDERER", "zeichen": "☲☶", "binaer_oben_nach_unten": "101100", "oben": "Feuer", "unten": "Berg", "bild_trigramme": "Feuer über Berg", "urteil": "Der Wanderer. Durch Kleinheit Gelingen.\nDem Wanderer ist Beharrlichkeit von Heil.", "bild": "Auf dem Berg ist Feuer: das Bild des Wanderers.\nSo ist der Edle klar und vorsichtig in der Anwendung von\nStrafen und verschleppt keine Streitigkeiten.", "quelle": {"url": "https://projekt-gutenberg.org/authors/richard-wilhelm/books/i-ging/chapter/41/", "text": "Richard Wilhelm, I Ging (1924), Projekt Gutenberg-DE"}, "karaoke": {"satz": "Finale · Vollendung", "datei": "lang-f-vollendung", "strophe": "F1", "zeile": "Bau-mei-ster, bau-uns-dei-nen-Hain", "start": 144, "gesamt_start": 1782, "stimme": "beide", "melodie": "M", "nr": 59, "pflanze": "Dach-Hauswurz (Sempervivum tectorum)", "sektor": 46}}, "57": {"king_wen": 57, "name": "Das Sanfte", "titel_quelle": "57. SUN / DAS SANFTE\n (DAS EINDRINGLICHE, DER WIND)", "zeichen": "☴☴", "binaer_oben_nach_unten": "110110", "oben": "Wind", "unten": "Wind", "bild_trigramme": "Wind über Wind", "urteil": "Das Sanfte. Durch Kleines Gelingen.\nFördernd ist es, zu haben, wohin man geht.\nFördernd ist es, den großen Mann zu sehen.", "bild": "Einander folgende Winde:\ndas Bild des Sanft-Eindringenden.\nSo verbreitet der Edle seine Gebote\nund wirkt seine Geschäfte.", "quelle": {"url": "https://projekt-gutenberg.org/authors/richard-wilhelm/books/i-ging/chapter/48/", "text": "Richard Wilhelm, I Ging (1924), Projekt Gutenberg-DE"}, "karaoke": {"satz": "C · I Ging", "datei": "lang-c-i-ging", "strophe": "C0", "zeile": "der-Bam-bus-singt, der-Gong-er-klingt", "start": 136, "gesamt_start": 1022, "stimme": "Frau", "melodie": "M", "nr": 31, "pflanze": "Echtes Federgras (Stipa pennata)", "sektor": 60}}, "58": {"king_wen": 58, "name": "Das Heitere", "titel_quelle": "58. DUI / DAS HEITERE, DER SEE", "zeichen": "☱☱", "binaer_oben_nach_unten": "011011", "oben": "See", "unten": "See", "bild_trigramme": "See über See", "urteil": "Das Heitere. Gelingen. Günstig ist Beharrlichkeit.", "bild": "Aufeinander beruhende Seen: das Bild des Heiteren.\nSo tut sich der Edle mit seinen Freunden zusammen zur\nBesprechung und Einübung.", "quelle": {"url": "https://projekt-gutenberg.org/authors/richard-wilhelm/books/i-ging/chapter/66/", "text": "Richard Wilhelm, I Ging (1924), Projekt Gutenberg-DE"}, "karaoke": {"satz": "B · Spiral Roll-out", "datei": "lang-b-spiral-roll-out", "strophe": "B1", "zeile": "und-schenkt-uns-ei-ne-Stun-de-Glück", "start": 104, "gesamt_start": 618, "stimme": "Bariton", "melodie": "S", "nr": 18, "pflanze": "Sibirische Schwertlilie (Iris sibirica)", "sektor": 10}}, "59": {"king_wen": 59, "name": "Die Auflösung", "titel_quelle": "59. HUAN / DIE AUFLÖSUNG", "zeichen": "☴☵", "binaer_oben_nach_unten": "110010", "oben": "Wind", "unten": "Wasser", "bild_trigramme": "Wind über Wasser", "urteil": "Die Auflösung. Gelingen.\nDer König naht seinem Tempel.\nFördernd ist es, das große Wasser zu durchqueren.\nFördernd ist Beharrlichkeit.", "bild": "Der Wind fährt über das Wasser: das Bild der Auflösung.\nSo opferten die alten Könige dem Herrn und bauten Tempel.", "quelle": {"url": "https://projekt-gutenberg.org/authors/richard-wilhelm/books/i-ging/chapter/32/", "text": "Richard Wilhelm, I Ging (1924), Projekt Gutenberg-DE"}, "karaoke": {"satz": "D · Begegnung", "datei": "lang-d-begegnung", "strophe": "D1", "zeile": "Ich-kom-me-von-dem-grü-nen-Meer", "start": 192, "gesamt_start": 1456, "stimme": "Bariton", "melodie": "M", "nr": 43, "pflanze": "Weicher Frauenmantel (Alchemilla mollis)", "sektor": 52}}, "60": {"king_wen": 60, "name": "Die Beschränkung", "titel_quelle": "60. DSIE / DIE BESCHRÄNKUNG", "zeichen": "☵☱", "binaer_oben_nach_unten": "010011", "oben": "Wasser", "unten": "See", "bild_trigramme": "Wasser über See", "urteil": "Beschränkung. Gelingen.\nBittere Beschränkung darf man nicht beharrlich üben.", "bild": "Oberhalb des Sees ist Wasser:\ndas Bild der Beschränkung\nSo schaut der Edle Zahl und Maß und untersucht,\nwas Tugend und rechter Wandel ist.", "quelle": {"url": "https://projekt-gutenberg.org/authors/richard-wilhelm/books/i-ging/chapter/62/", "text": "Richard Wilhelm, I Ging (1924), Projekt Gutenberg-DE"}, "karaoke": {"satz": "D · Begegnung", "datei": "lang-d-begegnung", "strophe": "D1", "zeile": "ich-brin-ge-dir-das-Har-fen-lied", "start": 208, "gesamt_start": 1472, "stimme": "Bariton", "melodie": "M", "nr": 45, "pflanze": "Sibirische Schwertlilie (Iris sibirica)", "sektor": 14}}, "61": {"king_wen": 61, "name": "Innere Wahrheit", "titel_quelle": "61. DSCHUNG FU / INNERE WAHRHEIT", "zeichen": "☴☱", "binaer_oben_nach_unten": "110011", "oben": "Wind", "unten": "See", "bild_trigramme": "Wind über See", "urteil": "Innere Wahrheit. Schweine und Fische. Heil !\nFördernd ist es, das große Wasser zu durchqueren. Fördernd ist Beharrlichkeit.", "bild": "Über dem See ist der Wind:\ndas Bild der inneren Wahrheit.\nSo bespricht der Edle die Strafsachen,\num Hinrichtungen aufzuhalten.", "quelle": {"url": "https://projekt-gutenberg.org/authors/richard-wilhelm/books/i-ging/chapter/64/", "text": "Richard Wilhelm, I Ging (1924), Projekt Gutenberg-DE"}, "karaoke": {"satz": "D · Begegnung", "datei": "lang-d-begegnung", "strophe": "D1", "zeile": "weil-je-der-Ton-auf-Lie-be-baut", "start": 232, "gesamt_start": 1496, "stimme": "Frau", "melodie": "S", "nr": 48, "pflanze": "Sibirische Schwertlilie (Iris sibirica)", "sektor": 13}}, "62": {"king_wen": 62, "name": "Des Kleinen Übergewicht", "titel_quelle": "62. SIAU GO / DES KLEINEN ÜBERGEWICHT", "zeichen": "☳☶", "binaer_oben_nach_unten": "001100", "oben": "Donner", "unten": "Berg", "bild_trigramme": "Donner über Berg", "urteil": "Des Kleinen Übergewicht. Gelingen.\nFördernd ist Beharrlichkeit.\nMan mag kleine Dinge tun, man soll nicht große Dinge tun.\nDer fliegende Vogel bringt die Botschaft:\n\"Es ist nicht gut, nach oben zu streben,\nes ist gut, unten zu bleiben. Großes Heil !", "bild": "Auf dem Berg ist der Donner:\ndas Bild von des Kleinen Übergewicht.\nSo legt der Edle im Wandel\ndas Übergewicht auf die Ehrerbietung.\nBei Trauerfällen legt er das Übergewicht auf die Trauer.\nBei seinen Ausgaben legt er\ndas Übergewicht auf die Sparsamkeit.", "quelle": {"url": "https://projekt-gutenberg.org/authors/richard-wilhelm/books/i-ging/chapter/37/", "text": "Richard Wilhelm, I Ging (1924), Projekt Gutenberg-DE"}, "karaoke": {"satz": "D · Begegnung", "datei": "lang-d-begegnung", "strophe": "D1", "zeile": "ich-kom-me-von-den-Ber-gen-her", "start": 200, "gesamt_start": 1464, "stimme": "Frau", "melodie": "S", "nr": 44, "pflanze": "Dach-Hauswurz (Sempervivum tectorum)", "sektor": 45}}, "63": {"king_wen": 63, "name": "Nach der Vollendung", "titel_quelle": "63. GI DSI / NACH DER VOLLENDUNG", "zeichen": "☵☲", "binaer_oben_nach_unten": "010101", "oben": "Wasser", "unten": "Feuer", "bild_trigramme": "Wasser über Feuer", "urteil": "Gelingen im Kleinen. Fördernd ist Beharrlichkeit.\nIm Anfang Heil, am Ende Wirren.", "bild": "Das Wasser ist oberhalb des Feuers:\ndas Bild des Zustands nach der Vollendung.\nSo bedenkt der Edle das Unglück\nund rüstet sich im voraus dagegen.", "quelle": {"url": "https://projekt-gutenberg.org/authors/richard-wilhelm/books/i-ging/chapter/54/", "text": "Richard Wilhelm, I Ging (1924), Projekt Gutenberg-DE"}, "karaoke": {"satz": "D · Begegnung", "datei": "lang-d-begegnung", "strophe": "D0", "zeile": "dass-Fremd-sein-bald-nur-Freund-schaft-sei", "start": 72, "gesamt_start": 1336, "stimme": "beide", "melodie": "S", "nr": 42, "pflanze": "Kartäuser-Nelke (Dianthus carthusianorum)", "sektor": 22}}, "64": {"king_wen": 64, "name": "Vor der Vollendung", "titel_quelle": "64. WE DSI / VOR DER VOLLENDUNG", "zeichen": "☲☵", "binaer_oben_nach_unten": "101010", "oben": "Feuer", "unten": "Wasser", "bild_trigramme": "Feuer über Wasser", "urteil": "Vor der Vollendung. Gelingen.\nWenn aber der kleine Fuchs,\nwenn er beinahe den Übergang vollendet hat,\nmit dem Schwanz ins Wasser kommt,\ndann ist nichts, das fördernd wäre.", "bild": "Das Feuer ist oberhalb des Wassers:\n das Bild des Zustands vor dem Übergang.\n So ist der Edle vorsichtig in der Unterscheidung der\n Dinge, damit jedes auf seinen Platz kommt.", "quelle": {"url": "https://projekt-gutenberg.org/authors/richard-wilhelm/books/i-ging/chapter/33/", "text": "Richard Wilhelm, I Ging (1924), Projekt Gutenberg-DE"}, "karaoke": {"satz": "A · Tanz der freundlichen Geister", "datei": "lang-a-tanz-der-freundlichen-geister", "strophe": "A", "zeile": "ein-Ring-aus-Blü-ten, hell-und-rund", "start": 88, "gesamt_start": 230, "stimme": "Bariton", "melodie": "S", "nr": 6, "pflanze": "Kartäuser-Nelke (Dianthus carthusianorum)", "sektor": 54}}}};
